 "content": "def transform(grid):
    # Each 3x3 patch encodes one output cell: take its non-background color.
    h, w = len(grid), len(grid[0])
    out = []
    for r in range(0, h, 3):
        row = []
        for c in range(0, w, 3):
            colors = {grid[i][j] for i in range(r, min(r + 3, h))
                      for j in range(c, min(c + 3, w)) if grid[i][j] != 5}
            if len(colors) != 1:
                raise ValueError(f"patch at {(r, c)} has colors {colors}")
            row.append(next(iter(colors)))
        out.append(row)
    return out
